INSERT INTO veg_vegetable (veg_name, alias, category, season, nutrition, purchase_tips, storage_method, price_ref) VALUES
('大白菜', '白菜,黄芽菜,结球白菜', '叶菜类', '秋冬', '富含维生素C、膳食纤维、钾；热量低，水分含量高，有助于促进肠道蠕动和补水。', '挑选叶片紧实、手感沉重、外叶鲜绿无黄叶的；根部切口新鲜不发黑。', '整棵用保鲜膜包裹，竖放于冰箱冷藏室（0-4℃），可保存1-2周；切开后切口用保鲜膜封好。', 1.50),
('菠菜', '波斯菜,赤根菜,鹦鹉菜', '叶菜类', '秋冬春', '富含铁、叶酸、维生素A、维生素K和抗氧化物质；有助于补血和维持视力健康。', '选叶片深绿肥厚、根部红润、茎部短壮的；避免叶片发黄或有斑点的。', '用湿纸巾包裹根部，装入保鲜袋冷藏（0-4℃），2-3天内食用最佳；不宜久存。', 3.50),
('生菜', '叶用莴苣,玻璃生菜,罗马生菜', '叶菜类', '春秋', '富含维生素A、维生素K、叶酸和水分；热量极低，适合减肥人群。', '选叶片翠绿饱满、无黄边、无虫眼的；整棵拿起来感觉松软有弹性。', '洗净沥干后用保鲜袋装好冷藏，尽量在3天内吃完；不要和苹果、香蕉一起存放。', 3.00),
('油麦菜', '莜麦菜,苦菜', '叶菜类', '春秋', '富含维生素A、维生素C、钙、铁；口感脆嫩，有清热解暑之效。', '选叶片深绿有光泽、茎部洁白粗壮、无黄叶的。', '用保鲜袋装好，放入冰箱冷藏室（0-4℃），2-3天内食用。', 3.00),
('韭菜', '壮阳草,扁菜,起阳草', '叶菜类', '春秋', '富含膳食纤维、维生素C、胡萝卜素和硫化物；有温中行气之功效。', '选叶片翠绿肥厚、根部洁白、有浓郁韭菜香气的。', '用厨房纸巾包好放入保鲜袋，冷藏可保存2-3天；不宜久存，最好现买现吃。', 4.00),
('芹菜', '旱芹,药芹,香芹', '叶菜类', '秋冬春', '富含膳食纤维、芹菜素、钾和维生素K；有助于降血压和促进消化。', '选茎秆粗壮挺直、叶片鲜绿、折断有清脆声的；茎部空心越少越好。', '用保鲜袋装好，根部朝下竖放冷藏；可保存一周左右。', 3.00),
('小白菜', '青菜,油菜,上海青,瓢儿白', '叶菜类', '全年', '富含维生素C、钙、铁和膳食纤维；钙含量在蔬菜中名列前茅。', '选叶片鲜绿无黄叶、茎部洁白饱满、整体小巧紧实的最佳。', '用湿纸巾包裹根部，保鲜袋装好冷藏，2-3天内食用。', 2.50),
('空心菜', '蕹菜,通菜,竹叶菜', '叶菜类', '夏秋', '富含叶绿素、膳食纤维、维生素A和铁；有清热解毒之功效。', '选茎叶翠绿、茎部中空明显、手感脆嫩的；避免茎部发黑变软的。', '不宜久存，用保鲜袋装好冷藏最多1-2天；最好当天食用。', 3.50),
('茼蒿', '蓬蒿,菊花菜,皇帝菜', '叶菜类', '秋冬春', '富含维生素A、维生素C、钙、铁和芳香挥发油；有安神健脑之功效。', '选叶片翠绿紧实、茎部短嫩、有浓郁清香味的。', '用保鲜袋装好冷藏，2-3天内食用；不宜久存。', 4.00),
('香菜', '芫荽,胡荽,香荽', '叶菜类', '春秋', '富含维生素C、胡萝卜素和挥发油；有健胃消食、驱风解毒之功效。', '选叶片翠绿水灵、根部带少许泥土更新鲜、香气浓郁的。', '根部用湿纸巾包裹，装入保鲜袋冷藏；或切碎后冷冻保存。', 5.00),
('娃娃菜', '微型大白菜,袖珍白菜', '叶菜类', '秋冬', '富含维生素C、膳食纤维、钾；口感细嫩甘甜，热量较低。', '选个头均匀、叶片紧实、色泽鲜黄、无虫眼的。', '保鲜膜包裹冷藏，可保存一周左右；切开后尽快食用。', 4.50),
('苋菜', '雁来红,老少年,三色苋', '叶菜类', '夏秋', '富含铁、钙、维生素K和花青素（红苋菜）；铁含量高于菠菜。', '选叶片鲜嫩、茎部脆嫩易折断、颜色鲜艳的。', '用保鲜袋装好冷藏，尽快在1-2天内食用。', 3.50);
INSERT INTO veg_vegetable (veg_name, alias, category, season, nutrition, purchase_tips, storage_method, price_ref) VALUES
('土豆', '马铃薯,洋芋,地蛋,山药蛋', '根茎类', '全年', '富含淀粉、维生素C、钾和膳食纤维；是全球第四大粮食作物。', '选表皮光滑无芽眼、无绿色、无破损的；发芽或表皮变绿的含龙葵素不宜食用。', '存放于阴凉通风干燥处（10-15℃），不要冷藏或与洋葱一起存放；避光保存防变绿。', 2.00),
('胡萝卜', '红萝卜,甘荀,金笋', '根茎类', '秋冬', '富含β-胡萝卜素（维生素A前体）、膳食纤维和抗氧化物质；对视力和皮肤有益。', '选色泽橙红均匀、表皮光滑、根部完整、手感结实的；顶部叶子新鲜翠绿更佳。', '去掉叶子后用保鲜袋装好冷藏，可保存2-3周；不要和苹果一起存放。', 2.50),
('白萝卜', '萝卜,莱菔,菜头', '根茎类', '秋冬', '富含维生素C、芥子油和膳食纤维；有消食化积、清热生津之功效。', '选表皮光滑白净、根须少、手感沉重结实的；敲击声音清脆为佳。', '去掉叶子，保鲜袋装好冷藏，可保存一周左右；切开后用保鲜膜封好。', 1.50),
('山药', '薯蓣,淮山,怀山药', '根茎类', '秋冬', '富含淀粉、黏蛋白、多糖、钾和多种氨基酸；有健脾养胃之功效。', '选表皮光滑无伤、根须完整、手感沉实的；铁棍山药品质最佳。', '整根用报纸包裹存放阴凉通风处；切开后切口涂白醋，保鲜膜包好冷藏。', 6.00),
('红薯', '甘薯,地瓜,番薯,红苕', '根茎类', '秋冬', '富含淀粉、β-胡萝卜素、膳食纤维和维生素C；升糖指数低于土豆。', '选表皮光滑无黑斑、无虫眼、手感结实的；纺锤形的最佳。', '存放于阴凉通风处（13-16℃），不要冷藏；冷藏会使淀粉转化为糖影响口感。', 3.00),
('莲藕', '藕,荷藕,玉节', '根茎类', '秋冬', '富含淀粉、维生素C、膳食纤维和铁；有清热凉血、健脾开胃之功效。', '选藕节粗壮饱满、表皮黄白、孔洞干净无泥的；两端藕节完整的更新鲜。', '整根用湿报纸包裹冷藏，可保存一周；切开后切口用保鲜膜封好防氧化变黑。', 5.00),
('洋葱', '圆葱,葱头,荷兰葱', '根茎类', '全年', '富含槲皮素、硫化物和膳食纤维；有抗氧化、降血脂之功效。', '选外皮干燥完整、手感硬实、无发芽无软烂的；扁圆形比圆形味道更甜。', '存放于阴凉通风干燥处，可保存数周至一个月；不要和土豆一起存放。', 2.00),
('芋头', '芋艿,芋奶,槟榔芋', '根茎类', '秋冬', '富含淀粉、膳食纤维、钾和氟；氟含量高有助于保护牙齿。', '选表皮完整无伤、手感沉重、切开后肉质细腻有紫色纹路的。', '存放于阴凉通风处；去皮后需浸水防氧化，冷藏可保存3-5天。', 4.00),
('竹笋', '笋,毛笋,冬笋,春笋', '根茎类', '春冬', '富含膳食纤维、蛋白质、B族维生素和多种矿物质；低脂肪低糖。', '选笋壳鲜亮紧包、根部切口新鲜、手感沉重的；冬笋肉质最嫩。', '带壳用保鲜袋装好冷藏，尽快在2-3天内食用；去壳后焯水可延长保存。', 8.00),
('莴笋', '莴苣,青笋,千金菜', '根茎类', '春秋', '富含维生素A、维生素K、钾和莴苣素；有清热利尿、镇静安神之功效。', '选茎秆粗壮均匀、表皮浅绿光滑、叶片鲜绿的；切口处汁液白嫩新鲜。', '去叶后用保鲜袋装好冷藏，可保存3-5天。', 3.00);
INSERT INTO veg_vegetable (veg_name, alias, category, season, nutrition, purchase_tips, storage_method, price_ref) VALUES
('番茄', '西红柿,洋柿子,六月柿', '瓜茄类', '夏秋', '富含番茄红素、维生素C、钾和有机酸；番茄红素是强抗氧化剂，加热后更易吸收。', '选色泽红润均匀、手感沉实有弹性、果蒂鲜绿的；自然成熟的底部有星状纹路。', '常温（阴凉处）保存，不要冷藏；冷藏会使风味物质流失、口感变差。', 3.50),
('黄瓜', '胡瓜,青瓜,王瓜', '瓜茄类', '夏秋', '富含水分（约96%）、维生素K、钾和黄瓜酶；热量极低，有清热解暑之效。', '选瓜条挺直、表皮深绿有刺、顶部带花的更新鲜；手感硬实的口感更脆。', '用保鲜袋装好冷藏（7-10℃），可保存3-5天；不要和番茄、苹果一起存放。', 2.50),
('茄子', '落苏,矮瓜,昆仑紫瓜', '瓜茄类', '夏秋', '富含花青素（紫茄皮）、膳食纤维、维生素P和钾；有助于增强血管弹性。', '选表皮紫黑有光泽、蒂部鲜绿带刺、手感沉实的；轻按有弹性不软塌。', '用保鲜袋装好冷藏，尽快在2-3天内食用；不宜久存。', 3.00),
('青椒', '甜椒,菜椒,柿子椒,灯笼椒', '瓜茄类', '夏秋', '富含维生素C（含量是柠檬的3倍）、β-胡萝卜素和膳食纤维；低热量。', '选表皮光滑有光泽、手感硬实、果柄鲜绿的；果形端正饱满的更脆甜。', '用保鲜袋装好冷藏，可保存一周左右。', 4.00),
('南瓜', '倭瓜,番瓜,金瓜,饭瓜', '瓜茄类', '夏秋', '富含β-胡萝卜素、南瓜多糖、钴和膳食纤维；对血糖调节有益。', '选表皮坚硬、色泽金黄、手感沉重、瓜蒂干枯的；老南瓜更甜更面。', '整个存放阴凉通风处可保存1-2个月；切开后去瓤去籽，保鲜膜包好冷藏。', 2.50),
('冬瓜', '白瓜,水芝,枕瓜', '瓜茄类', '夏秋', '富含水分、膳食纤维、维生素C和钾；热量极低，有利尿消肿之功效。', '选表皮深绿有白霜、手感沉重、无伤痕的；切开卖的选肉质洁白紧实的。', '整个存放阴凉处可保存1-2周；切开后去瓤，保鲜膜封好冷藏，尽快食用。', 2.00),
('苦瓜', '凉瓜,癞瓜,锦荔枝', '瓜茄类', '夏秋', '富含苦瓜苷、维生素C、膳食纤维和类胰岛素物质；有清热降糖之功效。', '选表皮瘤状突起饱满、色泽翠绿、手感硬实的；发黄过熟的苦味更重。', '用保鲜袋装好冷藏，可保存3-5天；不要和水果混放。', 4.50),
('丝瓜', '天罗,布瓜,胜瓜', '瓜茄类', '夏秋', '富含维生素B族、维生素C、膳食纤维和丝瓜皂苷；有清热化痰之功效。', '选瓜条匀称、表皮翠绿有光泽、手感硬实、两头粗细均匀的。', '用保鲜袋装好冷藏，尽快在2-3天内食用；碰伤后易腐烂。', 4.00),
('西葫芦', '角瓜,美洲南瓜,搅瓜', '瓜茄类', '夏秋', '富含水分、维生素C、钾和膳食纤维；热量极低，口感嫩滑。', '选表皮浅绿光滑、手感硬实、瓜体匀称的；长约15-20cm的口感最嫩。', '用保鲜袋装好冷藏，可保存3-5天；表皮易碰伤，轻拿轻放。', 3.00),
('辣椒', '尖椒,线椒,辣子,海椒', '瓜茄类', '夏秋', '富含辣椒素、维生素C（含量极高）和β-胡萝卜素；能促进新陈代谢。', '选表皮光滑有光泽、手感硬实、颜色鲜红或深绿的；弯尖的通常更辣。', '用保鲜袋装好冷藏，可保存一周；也可晒干或冷冻保存。', 5.00),
('秋葵', '羊角豆,咖啡黄葵,补肾菜', '瓜茄类', '夏秋', '富含黏蛋白、果胶、膳食纤维、钙和维生素K；有保护胃黏膜之功效。', '选长约5-10cm、色泽鲜绿、表面绒毛完整的；太长的口感老硬。', '用保鲜袋装好冷藏，2-3天内食用最佳；不宜久存。', 6.00),
('西兰花', '青花菜,绿菜花,意大利芥蓝', '瓜茄类', '秋冬', '富含萝卜硫素（强抗癌物质）、维生素C、维生素K和膳食纤维。', '选花球紧密深绿、花蕾细小均匀、茎部脆嫩的；无黄花的更新鲜。', '用保鲜袋装好冷藏，2-3天内食用；焯水后冷冻可长期保存。', 5.00);
INSERT INTO veg_vegetable (veg_name, alias, category, season, nutrition, purchase_tips, storage_method, price_ref) VALUES
('香菇', '冬菇,花菇,香菌,椎茸', '菌菇类', '全年', '富含香菇多糖、蛋白质、维生素D前体（麦角甾醇）和多种氨基酸；有增强免疫力之功效。', '选菇盖厚实圆整、边缘内卷、菇褶洁白、有浓郁香气的；干香菇选香味浓、无霉味的。', '鲜香菇用纸袋装好冷藏，2-3天内食用；干香菇密封存放阴凉干燥处。', 10.00),
('金针菇', '冬菇,毛柄金钱菌,智力菇', '菌菇类', '全年', '富含赖氨酸、精氨酸和锌；氨基酸组成全面，有助于儿童智力发育。', '选菇柄洁白挺直、菇盖小巧完整、无黏液、根部干净的。', '原包装冷藏，尽快在2-3天内食用；不宜清洗后存放。', 4.00),
('平菇', '侧耳,蚝菇,北风菌', '菌菇类', '秋冬春', '富含蛋白质、多糖和膳食纤维；含有的β-葡聚糖有助于降血脂。', '选菇盖灰白完整、边缘不破损、无黏液无霉斑的。', '用纸袋装好冷藏，2天内食用最佳；不能密封在塑料袋里。', 4.00),
('杏鲍菇', '刺芹菇,杏仁菇,鸡腿菇', '菌菇类', '全年', '富含蛋白质、膳食纤维和多糖；口感似鲍鱼，素食者的优质蛋白来源。', '选菇柄粗壮洁白、菇盖浅褐完整、手感弹性好的。', '用纸袋装好冷藏，2-3天内食用；可用厨房纸包裹吸潮。', 6.00),
('茶树菇', '茶薪菇,杨柳菌,柱状田头菇', '菌菇类', '全年', '富含蛋白质、氨基酸和多种微量元素；味道鲜美，有独特茶香。', '选菇柄细长挺直、菇盖完整、色泽浅褐的。', '用保鲜袋装好冷藏，尽快在2-3天内食用。', 8.00),
('木耳', '黑木耳,云耳,木蛾', '菌菇类', '全年', '富含铁、膳食纤维、多糖和植物胶质；铁含量是猪肝的7倍，有助于补血。', '干木耳选朵面乌黑有光泽、背面灰白、无碎渣的；泡发后肉质肥厚。', '干木耳密封存放阴凉干燥处；泡发后冷藏需在2天内食用。', 12.00),
('银耳', '白木耳,雪耳,银耳子', '菌菇类', '全年', '富含银耳多糖、膳食纤维和胶原蛋白前体；有滋阴润肺、美容养颜之功效。', '选朵大完整、色泽淡黄白、无黑点杂质、有清香的。', '密封存放阴凉干燥处，可保存较长时间；泡发后冷藏尽快食用。', 15.00),
('口蘑', '白蘑菇,洋菇,双孢菇', '菌菇类', '全年', '富含蛋白质、B族维生素、硒和钾；硒含量高，抗氧化效果好。', '选菇盖洁白圆整、菇褶粉红或浅褐、手感紧实的；菇盖打开的偏老。', '用纸袋装好冷藏，2-3天内食用；不要清洗后存放。', 8.00);
INSERT INTO veg_vegetable (veg_name, alias, category, season, nutrition, purchase_tips, storage_method, price_ref) VALUES
('四季豆', '菜豆,芸豆,刀豆,玉豆', '豆类', '夏秋', '富含蛋白质、膳食纤维、维生素K和B族维生素；含皂苷须充分煮熟后食用。', '选豆荚翠绿饱满、荚内豆粒不突出、折断有清脆声的；无锈斑无虫眼。', '用保鲜袋装好冷藏，3-5天内食用；焯水后冷冻可长期保存。', 4.50),
('豇豆', '长豆角,豆角,裙带豆', '豆类', '夏秋', '富含蛋白质、膳食纤维、维生素A和钾；有助于消化和维持血压稳定。', '选豆荚细长匀称、翠绿饱满、折断清脆、豆粒不明显的为嫩豆。', '用保鲜袋装好冷藏，2-3天内食用最佳。', 4.00),
('毛豆', '菜用大豆,枝豆,青豆', '豆类', '夏秋', '富含优质植物蛋白、卵磷脂、异黄酮和膳食纤维；大豆异黄酮有益女性健康。', '选豆荚饱满翠绿、荚面绒毛完整、有弹性的；剥开后豆粒饱满多汁。', '带荚冷藏，2-3天内食用；去荚焯水后可冷冻长期保存。', 5.00),
('豌豆', '青豆,荷兰豆(嫩荚),雪豆', '豆类', '春秋', '富含植物蛋白、膳食纤维、维生素C和叶酸；嫩荚荷兰豆维生素C含量高。', '选豆荚翠绿扁平、荚内豆粒不明显、折断脆嫩的；饱满鼓起的已偏老。', '用保鲜袋装好冷藏，2-3天内食用。', 6.00),
('蚕豆', '胡豆,罗汉豆,佛豆,川豆', '豆类', '春', '富含植物蛋白、膳食纤维、叶酸和左旋多巴；蛋白质含量在豆类中名列前茅。', '选豆荚饱满、剥开豆粒翠绿完整、种脐浅色的为嫩豆。', '带荚冷藏，2-3天内食用；去荚焯水后可冷冻保存。', 5.00),
('豆芽', '豆芽菜,绿豆芽,黄豆芽,芽苗菜', '豆类', '全年', '富含维生素C（发芽过程中大量合成）、叶酸和天冬氨酸；低热量高营养。', '选芽体洁白粗壮、根须少、无异味、水分充足的；黄豆芽选豆瓣金黄的。', '浸入清水中冷藏，每天换水，可保存2-3天。', 2.00),
('扁豆', '眉豆,蛾眉豆,鹊豆', '豆类', '夏秋', '富含蛋白质、膳食纤维、铁和B族维生素；白色扁豆药用价值较高。', '选豆荚饱满扁平、边缘无黑筋、手感脆嫩的。', '用保鲜袋装好冷藏，2-3天内食用。', 4.00),
('荷兰豆', '食荚豌豆,雪豆,甜豌豆', '豆类', '春秋', '富含维生素C、膳食纤维和叶绿素；整荚食用，营养更全面。', '选豆荚扁平翠绿、薄而透光、折断清脆有汁的；鼓起的已偏老。', '用保鲜袋装好冷藏，2-3天内食用最佳。', 6.00);
INSERT INTO veg_vegetable (veg_name, alias, category, season, nutrition, purchase_tips, storage_method, price_ref) VALUES
('玉米', '包谷,苞米,玉蜀黍,珍珠米', '其他', '夏秋', '富含碳水化合物、膳食纤维、叶黄素和玉米黄质；有助于保护视力。', '选苞叶鲜绿紧裹、玉米须棕褐湿润、籽粒饱满排列紧密的。', '带苞叶冷藏，2-3天内食用；去苞叶冷冻可长期保存。', 3.00),
('花菜', '花椰菜,菜花,白花菜', '其他', '秋冬', '富含萝卜硫素、维生素C和膳食纤维；十字花科蔬菜的典型代表。', '选花球紧密洁白、无黑斑黄斑、叶片鲜绿包裹的；松散的已偏老。', '整棵用保鲜袋装好冷藏，3-5天内食用；焯水后冷冻可长期保存。', 4.00),
('大蒜', '蒜,蒜头,胡蒜', '其他', '全年', '富含大蒜素（切开后生成）、硒和维生素B6；有抗菌消炎、降血脂之功效。', '选蒜头饱满结实、外皮完整干燥、无发芽无霉变的；紫皮蒜味更浓。', '存放阴凉通风干燥处，可保存1-2个月；不要冷藏。', 5.00),
('姜', '生姜,黄姜,老姜', '其他', '全年', '富含姜辣素、姜烯酚和挥发油；有驱寒暖胃、止呕之功效。', '选姜块饱满、表皮光滑淡黄、无腐烂无发芽的；老姜纤维多辣味重。', '存放阴凉通风处；切开后切口用保鲜膜封好冷藏。', 6.00),
('葱', '大葱,青葱,香葱,小葱', '其他', '全年', '富含葱辣素、维生素C和硒；有发汗解表、增进食欲之功效。', '选葱白粗壮洁白、葱叶翠绿挺直、根部完整的新鲜葱。', '根部用湿纸巾包裹，保鲜袋装好冷藏，可保存一周左右。', 3.00),
('芥蓝', '白花芥蓝,绿叶甘蓝,芥兰', '其他', '秋冬春', '富含维生素C、钙和膳食纤维；钙含量在蔬菜中名列前茅。', '选茎秆粗壮、花蕾未开、叶片翠绿的；茎部易折断表示新鲜。', '用保鲜袋装好冷藏，2-3天内食用。', 4.50),
('卷心菜', '圆白菜,包菜,甘蓝,洋白菜', '其他', '全年', '富含维生素U（抗溃疡因子）、维生素C和膳食纤维；有助于保护胃黏膜。', '选球形紧实、手感沉重、外叶翠绿、无裂口的；切开后内部洁白紧实。', '整棵存放阴凉通风处可保存1-2周；切开后用保鲜膜封好冷藏。', 2.00),
('紫甘蓝', '紫卷心菜,红甘蓝,紫苞菜', '其他', '秋冬', '富含花青素（天然紫色素）、维生素C和膳食纤维；抗氧化能力出色。', '选球形紧实、色泽紫红均匀、手感沉重的。', '整棵存放阴凉处可保存1-2周；切开后保鲜膜封好冷藏。', 3.50);
